Variable.Value:
using System;
using System.Drawing;
using System.Linq;
using System.Windows.Forms;
using Triggernometry.Core;
using Triggernometry.PluginBridges;
using Triggernometry.UI.CustomControls;
using Triggernometry.UI.Forms;
using static Triggernometry.Core.Scripting.ScriptHelper;
using static Triggernometry.UI.Forms.GameConfigForm;

const string KEY = "U7a";
var version = GetRegisteredVariable($"bby.{KEY}.Version") ??
    throw new InvalidOperationException($"缺少注册变量 bby.{KEY}.Version，无法注册配置窗口。");

var info = new ConfigInfo("绝伊甸宝宝椅", version, "阿洛 MnFeN", $"{KEY}_cfg");

RealPlugin.Instance.RegisterNamedCallback(
    info.ConfigName,
    new Action<object, string>((_, __) => ShowConfig(info, U7aEntry.Setup)));

public static class U7aEntry
{
    static readonly Color Blue = Color.FromArgb(0x22, 0x66, 0xff);

    public static void Setup(GameConfigForm form)
    {
        BijectDictionary<string, string> cbxItems;
        Option optionCtrl;
        Label label;
        string hint = "";
        // 在下面倒序添加各个选项组（组内的选项正序）

        #region 配置：P5

        OptionsTableLayoutPanel tableP5 = form.AddOptionGroup(" P5 潘多拉 ");

        // P5 挡枪顺序
        cbxItems = new BijectDictionary<string, string>(
            ("TMRH", " T 近 远 H（国服/美服）"),
            ("THMR", " T H 近 远"),
            ("TMRT", " T 近 远 T")
        );
        optionCtrl = new OptionCbx("　挡枪职能顺序", "P5挡枪", cbxItems, "TMRH", hint);
        form.AddOption(optionCtrl, tableP5);

        #endregion 配置：P5

        #region 配置：P4

        OptionsTableLayoutPanel tableP4 = form.AddOptionGroup(" P4 琳＆盖娅 ");
        form.AddLabel("· [P4 一运]", tableP4).ForeColor = Blue;

        // P4 一运
        cbxItems = new BijectDictionary<string, string>(
            ("翻绳THMR", " 国服翻绳（MT ST H1 H2 | D1-4）"),
            ("翻绳HTMR", " 日服翻绳（H1 H2 MT ST | D1-4）"),
            ("翻绳HTRM", " 美服翻绳（H1 H2 MT ST | D3 D4 D1 D2）"),
            ("分摊THD", " 分摊基准（MT ST H1 H2 | D1-4）（MMW 文档旧版）"),
            ("分摊HTD", " 分摊基准（H1 H2 MT ST | D1-4）"),
            ("分摊HTD41", " 分摊基准（H1 H2 MT ST | D4-1）"),
            ("分摊DHT", " 分摊基准（D4-1 | H2 H1 ST MT）（MMW 新版 上下倒转）")
        );
        hint = "翻绳打法：括号中为场地北、南两侧四人从西到东的顺序\n\n" +
               "分摊基准：括号中为场地西、东两侧四人从北到南的顺序";
        var optP4一运 = new OptionCbx("　一运解法", "P4一运", cbxItems, "翻绳THMR", hint);
        optP4一运.DataChanged += (sender, e) =>
        {
            form.GetOption("P4一运沙漏is主斜换").Enabled = optP4一运.Data.StartsWith("翻绳");
            form.GetOption("P4一运方形is左换").Enabled = optP4一运.Data.StartsWith("翻绳");
        };
